// Compute weekly claim statistics from the Claims records fetched above.
const items = $input.all();

const PENDING_STATUSES = ['Submitted', 'Under Review', 'Additional Documents Required'];
const DECIDED_STATUSES = ['Approved', 'Rejected', 'Closed'];

let approved = 0;
let rejected = 0;
let pending = 0;
let suspiciousCount = 0;
const claimTypeBreakdown = {};
const priorityBreakdown = {};
const processingTimesDays = [];
const claimLines = [];

for (const item of items) {
  // Handle both possible Airtable output shapes: nested under 'fields', or flattened onto $json directly
  const src = (item.json.fields && typeof item.json.fields === 'object') ? item.json.fields : item.json;
  const claimId = item.json.id;
  const claimantName = src['Claimant Name'] || 'Unknown';
  const claimType = src['Claim Type'] || 'Other';
  const status = src['Status'] || 'Submitted';
  const priority = src['Priority'] || 'Medium';
  const suspicious = src['Suspicious'] === true;
  const submittedDate = src['Submitted Date'];
  const createdTime = item.json.createdTime;

  if (status === 'Approved') approved++;
  else if (status === 'Rejected') rejected++;
  else if (PENDING_STATUSES.includes(status)) pending++;

  if (suspicious) suspiciousCount++;

  claimTypeBreakdown[claimType] = (claimTypeBreakdown[claimType] || 0) + 1;
  priorityBreakdown[priority] = (priorityBreakdown[priority] || 0) + 1;

  if (DECIDED_STATUSES.includes(status) && submittedDate && createdTime) {
    const days = (new Date(submittedDate) - new Date(createdTime)) / (1000 * 60 * 60 * 24);
    if (days >= 0) processingTimesDays.push(days);
  }

  claimLines.push(`${claimId} | ${claimantName} | ${claimType} | ${status} | ${priority}${suspicious ? ' | FLAGGED' : ''}`);
}

const totalClaims = items.length;
const avgProcessingDays = processingTimesDays.length
  ? Math.round((processingTimesDays.reduce((a, b) => a + b, 0) / processingTimesDays.length) * 10) / 10
  : 0;

const end = new Date();
const start = new Date(end.getTime() - 7 * 24 * 60 * 60 * 1000);
const fmt = (d) => d.toISOString().slice(0, 10);
const reportPeriod = `${fmt(start)} to ${fmt(end)}`;

return {
  json: {
    reportPeriod,
    totalClaims,
    approved,
    rejected,
    pending,
    suspiciousCount,
    avgProcessingDays,
    claimTypeBreakdown,
    priorityBreakdown,
    claimsSummaryText: claimLines.length ? claimLines.join('\n') : 'No claims recorded in this period.'
  }
};

