// Merge the computed stats with the AI-generated insights into the final report record.
const stats = $('Compute Report Stats').item.json;
const aiResponse = $json;

let aiInsights = 'AI insights unavailable for this period.';
try {
  const candidate = aiResponse.candidates && aiResponse.candidates[0];
  const content = candidate && candidate.content && candidate.content.parts && candidate.content.parts[0]
    ? candidate.content.parts[0].text
    : null;
  if (content) aiInsights = content.trim();
} catch (e) {
  // fall back to default message above
}

return {
  json: {
    reportPeriod: stats.reportPeriod,
    totalClaims: stats.totalClaims,
    approved: stats.approved,
    rejected: stats.rejected,
    pending: stats.pending,
    avgProcessingDays: stats.avgProcessingDays,
    suspiciousCount: stats.suspiciousCount,
    claimTypeBreakdown: stats.claimTypeBreakdown,
    priorityBreakdown: stats.priorityBreakdown,
    aiInsights,
    reportDate: $now.toISO()
  }
};

// Build the email subject/body for the weekly report notification.
const r = $('Build Report Record').item.json;

const typeLines = Object.entries(r.claimTypeBreakdown || {}).map(([k, v]) => `  - ${k}: ${v}`).join('\n');
const priorityLines = Object.entries(r.priorityBreakdown || {}).map(([k, v]) => `  - ${k}: ${v}`).join('\n');

const subject = `Weekly Claims Report: ${r.reportPeriod}`;

const body = `Weekly Insurance Claims Report (${r.reportPeriod})\n\n` +
  `Total Claims: ${r.totalClaims}\n` +
  `Approved: ${r.approved}\n` +
  `Rejected: ${r.rejected}\n` +
  `Pending: ${r.pending}\n` +
  `Flagged as Suspicious: ${r.suspiciousCount}\n` +
  `Average Processing Time: ${r.avgProcessingDays} days\n\n` +
  `Claims by Type:\n${typeLines || '  - none'}\n\n` +
  `Claims by Priority:\n${priorityLines || '  - none'}\n\n` +
  `AI Insights:\n${r.aiInsights}\n`;

// NOTE: replace with the real distribution address for your team
const recipientEmail = 'claims-team@example.com';

return {
  json: {
    recipientEmail,
    subject,
    body
  }
};
